"""Original Maths word cards and retrieval checks. Correct choice is rotated when built."""
R={}
def pack(key,cards,q,correct,wrong1,wrong2,why):
 R[key]={'cards':[dict(term=t.split('=',1)[0],definition=t.split('=',1)[1]) for t in cards.split('~')],'quiz':dict(q=q,opts=[correct,wrong1,wrong2],a=0,why=why)}

pack('sequence','Term=A number or item in a sequence.~Term-to-term rule=The instruction used to get from one term to the next.','What comes next in 3, 7, 11, 15?','19.','18.','60.','Add 4 each time: 15 + 4 = 19.')
pack('nonlinear','Arithmetic sequence=A sequence that adds the same amount each time.~Geometric sequence=A sequence that multiplies by the same number each time.','Which sequence multiplies by the same number each time?','2, 6, 18, 54.','2, 5, 8, 11.','1, 4, 9, 16.','Each term in 2, 6, 18, 54 is three times the one before.')
pack('nth','Nth-term rule=A rule that finds a term from its position n.~Position=Where a term appears in a sequence, starting at 1.','What is the fifth term of 3n + 2?','17.','15.','10.','Put n = 5 into the rule: 3 × 5 + 2 = 17.')
pack('quadratic-sequence','Second difference=The difference between neighbouring first differences.~Quadratic sequence=A sequence with an n² rule and a constant, non-zero second difference.','The second difference is 6. What number multiplies n² in a quadratic rule?','3.','6.','12.','The second difference is twice the n² coefficient, so divide 6 by 2.')
pack('function','Input=The starting number put into a function.~Inverse operation=An operation that undoes another, such as dividing to undo multiplying.','A machine does ×2 then +5. Which step do you undo first?','Subtract 5.','Divide by 2.','Add 5.','Work backwards by undoing the last operation first.')
pack('notation','Expression=A mathematical statement without an equals sign, such as 3x + 2.~Equation=A statement that two expressions have equal values.','What does 4a mean?','4 × a.','4 + a.','a × a × a × a.','A number written directly before a letter means multiply.')
pack('substitute','Substitution=Replacing a letter with its value.~Evaluate=Work out the value of an expression.','For x = −4, what is x²?','16.','−16.','−8.','Put the negative value in brackets: (−4) × (−4) = 16.')
pack('like','Like terms=Terms with exactly the same letters and powers.~Coefficient=The number multiplying a letter or a power.','Simplify 6x − 2x.','4x.','4.','4x².','Subtract the coefficients and keep the x: (6 − 2)x = 4x.')
pack('balance','Equality=Two quantities having the same value.~Solution=A value that makes an equation true.','Which keeps an equation balanced?','Subtract 3 from both sides.','Subtract 3 from only the left side.','Change just the unknown.','The same operation on both sides keeps their values equal.')
pack('equation','Solve=Find the value or values that make a statement true.~Check a solution=Put the answer into the original equation to see whether both sides match.','What is x if 2x + 3 = 11?','4.','7.','5.5.','Subtract 3 to get 2x = 8, then divide by 2.')
pack('both-sides','Unknown=A value you need to find, often shown by a letter.~Form an equation=Write two equal amounts using mathematical expressions and an equals sign.','What is x if 5x = 2x + 12?','4.','12.','3.','Subtract 2x to get 3x = 12, then divide by 3.')
pack('rearrange','Subject of a formula=The letter standing alone on one side of the equals sign.~Identity=A statement true for every allowed value, such as 2(x + 1) = 2x + 2.','Which makes x stand alone in y = 2x + 6?','x = (y − 6) ÷ 2.','x = y ÷ 2 + 6.','x = 2y − 6.','Subtract 6 from both sides before dividing the whole remaining expression by 2.')
pack('expand','Expand=Multiply out the brackets in an expression.~Factorise=Write an expression as factors multiplied together.','Expand 3(x + 4).','3x + 12.','3x + 4.','x + 12.','Multiply both x and 4 by 3.')
pack('double','Quadratic expression=An expression whose highest power of the unknown is 2.~Difference of squares=An expression a² − b², which factorises to (a − b)(a + b).','Expand (x + 2)(x + 3).','x² + 5x + 6.','x² + 6.','2x + 5.','The four products are x², 3x, 2x and 6. Combine 3x + 2x.')
pack('place','Place value=The value a digit has because of its position in a number.~Thousandth=One of a thousand equal parts of a whole, written 0.001.','Which is larger: 0.62 or 0.602?','0.62.','0.602.','They are equal.','Write 0.62 as 0.620, then compare hundredths.')
pack('round','Decimal place=A digit position to the right of the decimal point.~Significant figure=A digit counted from the first non-zero digit when rounding.','Round 4.768 to 2 decimal places.','4.77.','4.76.','4.8.','Keep the hundredths digit. The next digit, 8, rounds it up.')
pack('estimate','Estimate=A rough answer used to check the likely size of a result.~Error interval=The range of original values that would round to a stated measurement.','Which is a sensible estimate of 29.7 × 4.1?','30 × 4 = 120.','3 × 4 = 12.','30 + 4 = 34.','Round to nearby easy numbers, then keep the same operation.')
pack('add','Place-value column=A column for units, tenths or another fixed digit value.~Inverse check=A check that uses the operation that undoes the calculation.','Calculate 7.2 − 0.85.','6.35.','6.45.','7.115.','Write 7.20 − 0.85 and line up the decimal points.')
pack('multiply','Product=The result of multiplying numbers.~Power of ten=10 multiplied by itself a whole number of times, or its reciprocal for a negative power.','Calculate 0.6 × 0.4.','0.24.','2.4.','0.024.','6 × 4 = 24. The two starting decimal places give 0.24.')
pack('divide','Divisor=The number you divide by.~Quotient=The answer to a division.','Calculate 4.8 ÷ 0.6.','8.','0.8.','80.','Multiply both numbers by 10 to get 48 ÷ 6 = 8.')
pack('order','Order of operations=The agreed order for working out a calculation.~Square=Multiply a number by itself.','Calculate 10 + 2 × 3.','16.','36.','30.','Multiply first: 2 × 3 = 6, then add 10.')
pack('directed','Negative number=A number less than zero.~Opposite number=A number the same distance from zero on the other side, such as −4 and 4.','Calculate 3 − (−5).','8.','−2.','−8.','Subtracting a negative means adding its opposite: 3 + 5 = 8.')
pack('negative-products','Positive number=A number greater than zero.~Negative factor=A negative number being multiplied as part of a product.','Calculate (−4) × (−3).','12.','−12.','−7.','For multiplication, two negative factors give a positive product.')
pack('mean','Mean=The total of the values divided by how many values there are.~Median=The middle value in an ordered list, or the mean of the two middle values.~Range=The largest value minus the smallest.','Find the median of 7, 2, 9.','7.','2.','6.','Put the list in order: 2, 7, 9. The middle value is 7.')
pack('frequency','Frequency=How often a value or category occurs.~Class midpoint=The value halfway between the two ends of a grouped-data interval.','A value 4 has frequency 3. How much does it contribute to the total?','12.','7.','4/3.','The value appears three times: 4 + 4 + 4 = 12.')
pack('charts','Pictogram=A chart using symbols to show amounts.~Key=The explanation of what a symbol or label stands for.','One symbol represents 6 items. What do 2½ symbols represent?','15.','12.5.','9.','Two symbols represent 12 and half a symbol represents 3, giving 15.')
pack('scatter','Correlation=A pattern showing how two measurements change together.~Line of best fit=A line following the main pattern of points on a scatter graph.','What does negative correlation mean?','One measurement tends to fall as the other rises.','Both measurements must be negative.','There is no pattern at all.','Negative describes the downward pattern, not whether the plotted numbers are below zero.')
pack('coordinates','Coordinate pair=Two numbers (x, y) that locate a point on a grid.~Midpoint=The point halfway along a line segment.','Which coordinate is read first in (x, y)?','The horizontal x value.','The vertical y value.','Whichever value is positive.','Go along first, then up or down.')
pack('fdp','Numerator=The top number of a fraction, counting the parts taken.~Denominator=The bottom number, showing how many equal parts make a whole.~Percentage=An amount out of 100.','What percentage is 0.4?','40%.','4%.','0.4%.','Multiply the decimal by 100: 0.4 × 100 = 40.')
pack('equivalent','Equivalent fractions=Different-looking fractions with the same value.~Improper fraction=A fraction whose numerator is at least as large as its denominator.','Which fraction equals 2/3?','8/12.','2/6.','4/9.','Multiply the numerator and denominator by 4.')
pack('fraction-amount','Unit fraction=A fraction with numerator 1, such as 1/5.~Whole=The complete amount that a fraction describes a part of.','What is 3/4 of 20?','15.','5.','60.','One quarter is 20 ÷ 4 = 5. Three quarters are 5 × 3 = 15.')
pack('percent-amount','Percentage=An amount out of 100.~Multiplier=A number you multiply by to make a change or find an amount.','What is 15% of 60?','9.','15.','0.9.','10% is 6 and 5% is 3, so 15% is 9.')
pack('change','Percentage change=The change divided by the original amount, multiplied by 100%.~Original amount=The amount before a change happened.','Which multiplier increases a price by 20%?','1.2.','0.2.','0.8.','Keep the original 100% and add 20%, giving 120% = 1.2.')
pack('reverse','Reverse percentage=Finding the original amount before a percentage change.~Compound growth=Repeated growth where each change uses the latest amount.','A price after a 10% reduction is £45. Which calculation finds the original price?','45 ÷ 0.9.','45 × 0.9.','45 + 4.5.','The new price is 90% of the original, so divide by 0.9.')
pack('perimeter','Perimeter=The total distance around the outside of a shape.~Boundary=The outside edge of a shape.','A rectangle is 6 cm by 4 cm. What is its perimeter?','20 cm.','24 cm.','10 cm.','Add two lengths and two widths: 6 + 4 + 6 + 4 = 20 cm.')
pack('area','Area=The amount of surface a shape covers, measured in square units.~Perpendicular height=The height measured at right angles to the base.','A triangle has base 8 cm and perpendicular height 5 cm. What is its area?','20 cm².','40 cm².','13 cm².','A triangle is half a matching rectangle: ½ × 8 × 5 = 20 cm².')
pack('time','Elapsed time=How much time passes between a start and a finish.~Decimal hour=A time written as a decimal number of hours.','Write 30 minutes as decimal hours.','0.5 hours.','0.3 hours.','0.30 minutes.','There are 60 minutes in an hour, so 30 ÷ 60 = 0.5 hours.')
pack('speed','Average speed=Total distance divided by total time.~Rate=How much one quantity changes for each unit of another.','A cyclist travels 100 m in 20 seconds. What is the average speed?','5 m/s.','2000 m/s.','0.2 m/s.','Divide distance by time: 100 ÷ 20 = 5 m/s.')
pack('distancegraph','Gradient=The steepness of a line, found by dividing vertical change by horizontal change.~Stationary=Not moving.','What does a horizontal line on a distance–time graph show?','The object has stopped.','The object is moving uphill.','The object is speeding up.','Time passes but the distance does not change.')
pack('factors','Factor=A whole number that divides another whole number with no remainder.~Prime number=A positive whole number with exactly two positive factors, 1 and itself.','Which number is prime?','13.','1.','15.','13 has only the factors 1 and 13. The number 1 is not prime.')
pack('hcf','HCF=The highest common factor: the largest factor shared by the numbers.~LCM=The lowest common multiple: the smallest positive number in all the given times tables.','Find the HCF of 12 and 18.','6.','36.','3.','The shared factors are 1, 2, 3 and 6. The largest is 6.')
pack('fraction-add','Common denominator=A matching denominator used to combine or compare fractions.~Simplest form=A fraction whose numerator and denominator have no common factor above 1.','Calculate 1/2 + 1/3.','5/6.','2/5.','1/5.','Use sixths: 3/6 + 2/6 = 5/6.')
pack('fraction-algebra','Algebraic fraction=A fraction containing letters in its numerator or denominator.~Common factor=A factor shared by two or more expressions or numbers.','Simplify x/3 + x/6.','x/2.','2x/9.','x/9.','Rewrite x/3 as 2x/6. Then 3x/6 = x/2.')
pack('angles','Right angle=An angle of 90°.~Isosceles triangle=A triangle with two equal sides and two equal base angles.','Two angles in a triangle are 50° and 60°. What is the third?','70°.','110°.','250°.','Triangle angles add to 180°: 180 − 50 − 60 = 70°.')
pack('measure','Vertex=The point where the arms of an angle meet.~Reflex angle=An angle greater than 180° and less than 360°.','A smaller angle is 80°. What is its reflex partner?','280°.','100°.','440°.','A full turn is 360°: 360 − 80 = 280°.')
pack('ratio','Ratio=A comparison of amounts in a stated order.~Ratio unit=One equal part used to represent a share.','For red:blue = 2:3, what fraction of all counters are red?','2/5.','2/3.','3/5.','There are 5 equal parts altogether and 2 are red.')
pack('share','Share=The part of a total given to one person or group.~Ratio unit=One equal part in a ratio model.','Share 35 in the ratio 2:5. What is the smaller share?','10.','14.','5.','There are 7 units, so each is worth 5. The smaller share is 2 × 5 = 10.')
pack('proportion','Direct proportion=Two quantities changing by the same multiplier, with a fixed ratio.~Inverse proportion=Two quantities with a fixed product, so multiplying one divides the other by the same factor.','Three identical pens cost £4.50. How much do six cost?','£9.','£7.50.','£2.25.','Twice as many pens cost twice as much when the price per pen stays the same.')
pack('scale','Scale factor=The multiplier linking matching lengths.~Similar shapes=Shapes with equal matching angles and one shared scale factor for matching lengths.','At scale 1:100, what does 4 cm on a plan represent?','4 m.','400 m.','0.04 m.','4 × 100 = 400 cm, which is 4 m.')
pack('linear','Gradient=How steep a line is: change in y divided by change in x.~Y-intercept=Where a graph crosses the y-axis, at x = 0.','What is the gradient of y = 4x − 2?','4.','−2.','2.','In y = mx + c, the coefficient of x is the gradient m.')
pack('perpendicular','Parallel lines=Lines in a plane that stay the same distance apart and never meet.~Perpendicular lines=Lines that meet at a right angle.','A line has gradient 3. What is a perpendicular line gradient?','−1/3.','3.','1/3.','Perpendicular non-vertical gradients multiply to −1: 3 × (−1/3) = −1.')
pack('fraction-product','Reciprocal=A number that multiplies with the original number to make 1.~Improper fraction=A fraction with numerator at least as large as its denominator.','What is the reciprocal of 3/7?','7/3.','−3/7.','1/7.','Turn the fraction over. 3/7 × 7/3 = 1.')
pack('symmetry','Reflection=A flip across a mirror line, keeping each point the same right-angle distance from the line.~Line symmetry=A shape matching itself when reflected in a line.','Reflect (2, 3) in the x-axis. What is the image?','(2, −3).','(−2, 3).','(3, 2).','The x value stays the same and the y value changes sign.')
pack('volume','Volume=The space a three-dimensional shape occupies, measured in cubic units.~Prism=A solid with the same cross-section all the way along.','What is the volume of a 2 cm by 3 cm by 4 cm cuboid?','24 cm³.','9 cm³.','24 cm².','Multiply all three lengths: 2 × 3 × 4 = 24 cm³.')
pack('density','Density=Mass per unit volume, calculated as mass divided by volume.~Capacity=The amount a container can hold.','An object has mass 80 g and volume 20 cm³. What is its density?','4 g/cm³.','1600 g/cm³.','0.25 g/cm³.','Density = 80 ÷ 20 = 4 g/cm³.')
pack('inequality','Inequality=A statement that one expression is larger or smaller than another, possibly including equality.~Boundary value=The value at the end of a solution interval.','Solve −2x < 8.','x > −4.','x < −4.','x > 4.','Divide by −2 and reverse the sign because you divided by a negative number.')
pack('parallel','Regular polygon=A closed straight-sided shape with equal sides and equal angles.~Exterior angle=The angle between a side and the extension of a neighbouring side.','What is each exterior angle of a regular pentagon?','72°.','108°.','36°.','A full set of exterior angles adds to 360°: 360 ÷ 5 = 72°.')
pack('probability','Probability=A number from 0 to 1 describing how likely an outcome is.~Complement=All outcomes where the stated event does not happen.','If P(rain) = 0.3, what is P(no rain)?','0.7.','1.3.','0.3.','An event and its complement add to 1: 1 − 0.3 = 0.7.')
pack('tables','Two-way table=A table sorting the same group by two categories.~Sample space=The complete set of possible outcomes for the choice being made.','A question chooses from 12 cyclists in a group of 30. Which total goes in the probability denominator?','12.','30.','42.','The choice is from the cyclists only, so the total is 12.')
pack('circle','Radius=The distance from the centre of a circle to its edge.~Diameter=A straight line across a circle through the centre, equal to two radii.~Circumference=The distance around a circle.','A circle has diameter 12 cm. What is its radius?','6 cm.','24 cm.','12 cm.','The radius is half the diameter: 12 ÷ 2 = 6 cm.')
pack('cylinder','Cylinder=A prism with a circular cross-section.~Cone=A solid with a circular base tapering to a point.','A cylinder has volume 60 cm³. What is the volume of a cone with the same base and perpendicular height?','20 cm³.','30 cm³.','180 cm³.','The cone has one third of the matching cylinder volume.')
pack('pie','Sector=A slice of a circle between two radii and an arc.~Frequency=How often an outcome or category occurs.','What angle represents one quarter of a pie chart?','90°.','25°.','180°.','A full circle is 360°, so a quarter is 360 ÷ 4 = 90°.')
pack('indices','Index=The power telling how many times a base is used as a factor.~Square root=A number that gives the original value when multiplied by itself.','Simplify 2³ × 2⁴.','2⁷.','2¹².','4⁷.','For matching bases, add the powers when multiplying: 3 + 4 = 7.')
pack('standard','Standard form=A number written as A × 10ⁿ, with 1 ≤ A < 10 for positive numbers and integer n.~Integer=A whole number, including zero and negative whole numbers.','Which is in standard form?','4.2 × 10⁵.','42 × 10⁴.','0.42 × 10⁶.','The number before ×10 must be at least 1 and less than 10 for a positive value.')
pack('surds','Surd=A root that cannot be written exactly as a fraction, such as √2.~Rationalise=Remove a root from a fraction denominator without changing the value.','Simplify √50.','5√2.','25√2.','√25 + √25.','50 = 25 × 2, so √50 = 5√2.')
pack('counting','Product rule=Multiply the number of choices at each stage to count combinations.~Systematic list=A list organised so no possibilities are missed or repeated.','There are 4 tops and 3 pairs of trousers. How many outfits are possible?','12.','7.','1.','Each of 4 tops can match 3 trousers: 4 × 3 = 12.')
pack('recurring','Recurring decimal=A decimal whose digit or block of digits repeats forever.~Terminating decimal=A decimal that ends after a finite number of digits.','Which is recurring?','0.333333… continuing forever.','0.25.','0.125.','A recurring decimal repeats without ending. The other two decimals finish.')
pack('pythagoras','Hypotenuse=The longest side of a right-angled triangle, opposite the right angle.~Pythagoras theorem=For a right-angled triangle, a² + b² = c² where c is the hypotenuse.','The shorter sides of a right triangle are 3 and 4. What is the hypotenuse?','5.','7.','25.','3² + 4² = 25, so take the square root: 5.')
pack('trig','Opposite side=The side across from your chosen angle in a triangle.~Adjacent side=The side next to your chosen angle, excluding the hypotenuse.','Which ratio is sine in a right triangle?','Opposite ÷ hypotenuse.','Adjacent ÷ hypotenuse.','Opposite ÷ adjacent.','SOH reminds you: sine equals opposite over hypotenuse.')
pack('trig-exact','Angle of elevation=An angle measured upwards from a horizontal line.~Angle of depression=An angle measured downwards from a horizontal line.','What is the exact value of sin 30°?','1/2.','√3/2.','1.','A 30°–60°–90° triangle gives sin 30° = 1/2.')
pack('histogram','Frequency density=Frequency divided by class width, used for histogram bar height.~Class width=The difference between the upper and lower class boundaries.','A histogram class has frequency 18 and width 6. What is its density?','3.','108.','12.','Density = 18 ÷ 6 = 3.')
pack('stem','Stem-and-leaf diagram=A display separating each value into a stem and leaf while keeping individual data.~Key=The explanation of how to read the place values in a diagram.','With key 2 ¦ 4 = 24, what does 3 ¦ 7 mean?','37.','3.7.','73.','The stem is tens and the leaf is units, so the value is 37.')
pack('velocitygraph','Acceleration=The change in velocity each second.~Displacement=Change in position, including direction, from start to finish.','What does the gradient of a velocity–time graph give?','Acceleration.','Distance.','Mass.','Gradient is change in velocity divided by change in time.')
pack('curves','Parabola=The curved shape of a quadratic graph.~X-intercept=A point where a graph crosses or touches the x-axis, so y = 0.','Where are the x-intercepts of y = x² − 16?','x = −4 and x = 4.','Only x = 4.','x = −16 and x = 16.','Set y to zero: x² = 16. Both −4 and 4 square to 16.')

# Extra short questions for the four units containing only one lesson.
for key,q,scheme in [
 ('symmetry','What is the order of rotational symmetry of a non-square rectangle?','2: it matches itself twice during a full turn.'),
 ('inequality','List the whole numbers that satisfy 0 ≤ x < 3.','0, 1 and 2.'),
 ('scatter','Is predicting inside the measured data range called interpolation or extrapolation?','Interpolation.'),
 ('curves','For y = x² − 4, find y when x = 0.','y = −4.')]:
 R[key]['review']={'q':q,'ms':[scheme],'m':1}
